import itertools, json, math, random
from urban_micro import effect_matrix_hotspot_report as hotspot

def row(t, c, d):
    return (t, c, 0.0, float(d), d, 0.0, 0.0, 0.0)

def reference(details, neighbors, minutes=60, alpha=0.05):
    # bucket -> cell -> [sum, count]
    bk = {}
    for t,c,*_, d,_,_,_ in [(r[0],r[1],*r[2:]) for r in details]:
        pass
    bk = {}
    for r in details:
        t,c,d = r[0],r[1],r[4]
        B=(t//(minutes*60))*(minutes*60)
        bk.setdefault(B,{}).setdefault(c,[0,0]); bk[B][c][0]+=d; bk[B][c][1]+=1
    recs=[]  # (B,c,n,L,p,x,v)
    for B in sorted(bk):
        cells=sorted(bk[B]); n=len(cells)
        d=[bk[B][c][0]/bk[B][c][1] for c in cells]
        pos={c:i for i,c in enumerate(cells)}
        adj=[set() for _ in cells]
        for a,b in neighbors:
            if a in pos and b in pos:
                adj[pos[a]].add(pos[b]); adj[pos[b]].add(pos[a])
        m=sum(d)/n; x=[v-m for v in d]; S=sum(v*v for v in x)
        v=[sum(x[j] for j in adj[i]) for i in range(n)]
        if S==0:
            L=[0.0]*n; p=[1.0]*n
        else:
            L=[n*x[i]*v[i]/S for i in range(n)]
            p=[1.0]*n; nf=math.factorial(n)
            for i in range(n):
                if not adj[i]: continue
                hits=0
                for perm in itertools.permutations(d):
                    xp=[q-sum(perm)/n for q in perm]
                    Li=n*xp[i]*sum(xp[j] for j in adj[i])/sum(z*z for z in xp)
                    if abs(Li)>=abs(L[i])-1e-12: hits+=1
                p[i]=hits/nf
        for i,c in enumerate(cells):
            recs.append((B,c,n,L[i],p[i],x[i],v[i]))
    N=len(recs)
    order=sorted(range(N), key=lambda i:(recs[i][4],recs[i][0],recs[i][1]))
    q=[0.0]*N; run=1.0
    for r in range(N,0,-1):
        i=order[r-1]; run=min(run, N*recs[i][4]/r); q[i]=min(1.0,run)
    out=[]
    for i,(B,c,n,L,p,x,vv) in enumerate(recs):
        rej=q[i]<=alpha
        kind="NS"
        if rej and x!=0 and vv!=0:
            kind={(1,1):"HH",(-1,-1):"LL",(1,-1):"HL",(-1,1):"LH"}[(1 if x>0 else -1, 1 if vv>0 else -1)]
        out.append((B,c,n,L,p,q[i],rej,kind))
    return out

