for trial in range(60):
    ncells=random.randint(1,6)
    cells=[chr(ord('a')+i) for i in range(ncells)]
    edges=set()
    for a in cells:
        for b in cells:
            if a<b and random.random()<0.4: edges.add((a,b))
    details=[]
    for c in cells:
        for t in random.sample(range(0,3*3600,60), random.randint(1,3)):
            details.append(row(t, c, round(random.uniform(-3,5),3)))
    alpha=random.choice([0.01,0.05,0.1,0.5,1.0])
    minutes=random.choice([60,30,120])
    rep=json.loads(hotspot(details, sorted(edges), minutes=minutes, alpha=alpha))
    ref=reference(details, sorted(edges), minutes, alpha)
    assert len(rep["groups"])==len({r[0] for r in ref})
    got=[(g["key"],ce["key"],g["n"],ce["local"],ce["p"],ce["q"],ce["reject"],ce["kind"])
         for g in rep["groups"] for ce in g["cells"]]
    assert len(got)==len(ref), (len(got),len(ref))
    for g,r in zip(got,ref):
        assert g[0]==r[0] and g[1]==r[1] and g[2]==r[2]
